mapper.select:
SELECT COALESCE(SUM(CASE WHEN t.rate < 60 THEN 1 ELSE 0 END), 0) AS seg0, COALESCE(SUM(CASE WHEN t.rate >= 60 AND t.rate < 70 THEN 1 ELSE 0 END), 0) AS seg1, COALESCE(SUM(CASE WHEN t.rate >= 70 AND t.rate < 80 THEN 1 ELSE 0 END), 0) AS seg2, COALESCE(SUM(CASE WHEN t.rate >= 80 AND t.rate < 90 THEN 1 ELSE 0 END), 0) AS seg3, COALESCE(SUM(CASE WHEN t.rate >= 90 THEN 1 ELSE 0 END), 0) AS seg4 FROM (SELECT r.total_score / NULLIF(p.total_score, 0) * 100 AS rate FROM an_exam_record r JOIN ex_exam e ON e.id = r.exam_id AND e.deleted = 0 JOIN ex_paper p ON p.id = e.paper_id WHERE r.status IN (1, 2, 3) AND r.total_score IS NOT NULL
AND e.id = #{examId}
) t

